def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    # The 6 marker indicates the reflection direction. A T-shaped marker
    # points toward the side opposite the reflected copy.
    row_counts = {}
    col_counts = {}
    for r, c in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1
    rows = sorted(row_counts)
    maxrow = max(rows, key=lambda r: row_counts[r])
    vertical_stem = (maxrow == rows[0] or maxrow == rows[-1]) and len(rows) >= 3

    for r, c in sixes:
        out[r][c] = 0

    if vertical_stem:
        rmin = min(r for r, c in fours)
        rmax = max(r for r, c in fours)
        cmin = min(c for r, c in fours)
        cmax = max(c for r, c in fours)
        if maxrow == rows[0]:  # marker points down; reflect to the right
            for r, c in fours:
                cc = 2 * cmax + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:  # marker points up; reflect to the left
            for r, c in fours:
                cc = 2 * cmin - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        rmax = max(r for r, c in fours)
        for r, c in fours:
            rr = 2 * rmax + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4

    return out
